// Adapter is a AWS VPC API implementation of the domain.Adapter interface
type Adapter struct {
	client           *ec2.Client
	networkACLID     string
	allowedRuleRange aclRuleNumberRange
}

type aclRuleNumberRange struct {
	min int64
	max int64
}

// NewAWSNetworkACLAdapter is a constructor for Adapter
func NewAWSNetworkACLAdapter(client *ec2.Client, networkACLID string, numberRange string) *Adapter {
	nRange := strings.SplitN(numberRange, "-", 2)
	min, _ := strconv.ParseInt(nRange[0], 10, 0)
	max, _ := strconv.ParseInt(nRange[1], 10, 0)

	return &Adapter{
		client:           client,
		networkACLID:     networkACLID,
		allowedRuleRange: aclRuleNumberRange{min: min, max: max},
	}
}

// ToString satisfies the domain.Adapter interface
func (a *Adapter) ToString() string {
	return "aws-network-acl"
}

// CreateRules satisfies the domain.Adapter interface
func (a *Adapter) CreateRules(rules []domain.Rule) (result domain.AdapterResult) {
	currentEntries := a.getPersistedACLEntries()
	highestRN := currentEntries.highestNumber
	if highestRN < a.allowedRuleRange.min {
		highestRN = a.allowedRuleRange.min
	}

	if a.allowedRuleRange.max < (highestRN + int64(len(rules))) {
		return domain.AdapterResult{Error: errors.New("not enough rule numbers available")}
	}

	for i, rule := range rules {
		if currentEntries.findByRule(rule) != nil {
			continue
		}

		n := highestRN + int64(i+1)
		req := a.client.CreateNetworkAclEntryRequest(createAddEntryInput(rule, a.networkACLID, n))

		_, err := req.Send(context.TODO())
		if err != nil {
			return domain.AdapterResult{Error: err}
		}
	}

	return domain.AdapterResult{}
}

// DeleteRules satisfies the domain.Adapter interface
func (a *Adapter) DeleteRules(rules []domain.Rule) (result domain.AdapterResult) {
	currentEntries := a.getPersistedACLEntries()
	for _, rule := range rules {
		persistedRule := currentEntries.findByRule(rule)
		if persistedRule == nil {
			continue
		}

		req := a.client.DeleteNetworkAclEntryRequest(createDeleteEntryInput(persistedRule, a.networkACLID))
		_, _ = req.Send(context.TODO())
	}

	return domain.AdapterResult{}
}

func (a *Adapter) getPersistedACLEntries() *EntryCollection {
	input := &ec2.DescribeNetworkAclsInput{
		NetworkAclIds: []string{
			a.networkACLID,
		},
		Filters: []ec2.Filter{
			{
				Name:   aws.String("entry.rule-action"),
				Values: []string{"allow"},
			},
		},
	}

	req := a.client.DescribeNetworkAclsRequest(input)
	resp, err := req.Send(context.Background())
	if err != nil || len(resp.NetworkAcls) == 0 {
		return NewEntryCollection(nil) // todo log error
	}

	return NewEntryCollection(resp.NetworkAcls[0].Entries) // Assume only 1 result because we filtered
}
package vpc

import (
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/ec2"
	"github.com/nstapelbroek/gatekeeper/domain"
	"net"
	"strconv"
)

type EntryCollection struct {
	entries       map[string][]ec2.NetworkAclEntry
	highestNumber int64
}

func (c EntryCollection) findByRule(rule domain.Rule) *ec2.NetworkAclEntry {
	persistedRules, found := c.entries[rule.String()]
	if !found {
		return nil
	}

	for i := range persistedRules {
		if persistedRules[i].RuleAction == ec2.RuleActionAllow {
			return &persistedRules[i]
		}
	}

	return nil
}

// NewACLEntryCollection is a constructor for ACLEntryCollection
func NewEntryCollection(entries []ec2.NetworkAclEntry) *EntryCollection {
	c := &EntryCollection{
		entries:       make(map[string][]ec2.NetworkAclEntry),
		highestNumber: 0,
	}

	for _, entry := range entries {
		rule, err := networkEntryToRule(entry)
		if err != nil {
			// todo warn ignored rule
			continue
		}

		c.entries[rule.String()] = append(c.entries[rule.String()], entry)
		ruleNumber := *entry.RuleNumber
		if ruleNumber > c.highestNumber {
			c.highestNumber = ruleNumber
		}
	}

	return c
}

func networkEntryToRule(entry ec2.NetworkAclEntry) (*domain.Rule, error) {
	cidr := entry.Ipv6CidrBlock
	if cidr == nil {
		cidr = entry.CidrBlock
	}
	ip, ipNet, err := net.ParseCIDR(*cidr)
	if err != nil {
		return nil, err
	}

	protocol, err := domain.NewProtocolFromString(*entry.Protocol)
	if err != nil {
		return nil, err
	}

	direction := domain.Inbound
	if *entry.Egress {
		direction = domain.Outbound
	}

	return &domain.Rule{
		Direction: direction,
		Protocol:  protocol,
		IPNet:     net.IPNet{IP: ip, Mask: ipNet.Mask},
		Port: domain.PortRange{
			BeginPort: *entry.PortRange.From,
			EndPort:   *entry.PortRange.To,
		},
	}, nil
}

func createAddEntryInput(rule domain.Rule, networkAclID string, ruleNumber int64) *ec2.CreateNetworkAclEntryInput {
	input := &ec2.CreateNetworkAclEntryInput{
		CidrBlock:    aws.String(rule.IPNet.String()),
		Egress:       aws.Bool(rule.Direction.IsOutbound()),
		NetworkAclId: aws.String(networkAclID),
		PortRange:    &ec2.PortRange{From: aws.Int64(rule.Port.BeginPort), To: aws.Int64(rule.Port.EndPort)},
		Protocol:     aws.String(strconv.Itoa(rule.Protocol.ProtocolNumber())),
		RuleAction:   "allow",
		RuleNumber:   aws.Int64(ruleNumber),
	}

	if rule.IPNet.IP.To4() == nil {
		input.Ipv6CidrBlock = input.CidrBlock
		input.CidrBlock = nil
	}

	return input
}

func createDeleteEntryInput(persistedRule *ec2.NetworkAclEntry, networkAclID string) *ec2.DeleteNetworkAclEntryInput {
	return &ec2.DeleteNetworkAclEntryInput{
		Egress:       persistedRule.Egress,
		NetworkAclId: aws.String(networkAclID),
		RuleNumber:   persistedRule.RuleNumber,
	}
}

